// @vitest-environment jsdom
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";
import { ALLOWED_PROTOCOLS, emojiOf, type InlineToken, tokenizeInline, uriProtocol } from "../src/phizziwig/inline";

// Generated by scripts/generate-inline-fixtures.mjs from the PHP engine. (Read
// by path: jsdom's URL is not one Node's file functions take.)
const fixtures: { text: string; html: string }[] = JSON.parse(
  readFileSync(fileURLToPath(import.meta.url).replace(/inline\.test\.ts$/, "fixtures/inline.json"), "utf8"),
);

// What exists in the dev instance (dev/phorge/seed.php); the fixtures name
// nothing else that exists.
const OBJECTS = new Set(["T1", "F1"]);
const USERS = new Set(["alice"]);
const PROJECTS = new Set(["demo_project"]);
const isMacro = (name: string): boolean => name === "rmecat";
const CONFIG = new Set(["phabricator.base-uri"]);
const EVAL: Record<string, string> = { "strings.platform.server.name": "Phorge" };

// Phorge's rendering and the tokens are both turned into a skeleton: the
// text, formatting as <b>, <i>, <s>, <u>, <h> (highlight) and <tt>, and
// whatever the server renders as one thing as [kind] ([a:text] for links).
const FORMAT_TAGS: Partial<Record<InlineToken["kind"], string>> = {
  bold: "b",
  italic: "i",
  del: "s",
  underline: "u",
  highlight: "h",
};
// The text of a link without a name is the page's title or the full URI,
// which the tokens do not tell: it matches any text.
const ANY = "\uE001";

/** The skeleton of Phorge's HTML, as a browser parses it. */
function htmlSkeleton(html: string): string {
  // A paragraph is "<p>…</p>". Parsed without the <p>, so that an embedded
  // image's <div> does not end the paragraph (and move what follows).
  const root = document.createElement("div");
  root.innerHTML = html.replace(/^<p>/, "").replace(/<\/p>$/, "");
  return normalize(nodeSkeleton(root));
}

function nodeSkeleton(node: Node): string {
  let out = "";
  for (const child of Array.from(node.childNodes)) {
    if (!(child instanceof Element)) {
      out += child.textContent;
      continue;
    }
    const tag = child.tagName.toLowerCase();
    const is = (selector: string): boolean => child.matches(selector);
    const format = { strong: "b", em: "i", del: "s", u: "u" }[tag] ?? (is("span.remarkup-highlight") ? "h" : null);
    if (format) {
      out += `<${format}>${nodeSkeleton(child)}</${format}>`;
    } else if (is("tt.remarkup-monospaced")) {
      out += `<tt>${child.textContent}</tt>`;
    } else if (tag === "br") {
      // The "\n" after it is text.
    } else if (is("a.remarkup-link, a[class^=phriction-link]")) {
      out += `[a:${child.textContent}]`;
    } else if (is("a.atom-ref, a[href^='/config/edit/']")) {
      out += "[sym]";
    } else if (is("a.phui-tag-view")) {
      out += "[ref]";
    } else if (is("span.phabricator-remarkup-mention-unknown")) {
      out += `[unknown:${child.textContent}]`;
    } else if (is("img, div[class^=phabricator-remarkup-embed]")) {
      out += "[img]";
    } else if (is("span.phui-icon-view")) {
      out += "[icon]";
    } else if (is("kbd, span.kbd-join")) {
      out += "[key]";
    } else if (is("span.remarkup-nav-sequence")) {
      out += "[nav]";
    } else if (is("a[name]")) {
      out += "[anchor]";
    } else if (is("span.phui-tag-view")) {
      // The error {src …} renders without a repository.
      out += "[src]";
    } else {
      out += `[?${tag}.${child.className}]`;
    }
  }
  return out;
}

/** The skeleton of the tokens, rendered the way the dev instance renders them. */
function tokenSkeleton(text: string, tokens: InlineToken[], from: number, to: number): string {
  let out = "";
  let at = from;
  for (const token of tokens) {
    out += text.slice(at, token.from);
    out += renderToken(text, token);
    at = token.to;
  }
  return out + text.slice(at, to);
}

function renderToken(text: string, token: InlineToken): string {
  // Text Phorge renders as it is, with the emoji in it.
  const source = tokenSkeleton(text, token.children ?? [], token.from, token.to);
  const content = token.contentFrom === undefined ? null : text.slice(token.contentFrom, token.contentTo);
  const inner = (): string => tokenSkeleton(text, token.children ?? [], token.contentFrom!, token.contentTo!);
  const format = FORMAT_TAGS[token.kind];
  if (format) {
    return `<${format}>${inner()}</${format}>`;
  }
  switch (token.kind) {
    case "monospace":
      return `<tt>${inner()}</tt>`;
    case "eval":
      return EVAL[source.slice(4, -3)] ?? source;
    case "emoji":
      return emojiOf(text.slice(token.from + 1, token.to - 1))!;
    case "link":
      return `[a:${content ?? ANY}]`;
    case "url": {
      // "{uri}" renders as text; a protocol Phorge does not link as the URI.
      if (source.startsWith("{")) {
        return source;
      }
      const uri =
        token.contentFrom === undefined
          ? source
          : tokenSkeleton(text, token.children ?? [], token.contentFrom, token.contentTo!);
      return ALLOWED_PROTOCOLS.has(uriProtocol(uri) ?? "") ? `[a:${uri}]` : uri;
    }
    case "object":
      return OBJECTS.has(source.replace(/#.*/, "")) ? "[ref]" : source;
    case "embed": {
      const name = /^\{([^,\s}]+)/.exec(source)![1];
      if (name === "F1") {
        return "[img]";
      }
      return OBJECTS.has(name) || PROJECTS.has(name.slice(1)) ? "[ref]" : source;
    }
    case "project":
      return PROJECTS.has(source.slice(1).replace(/#.*/, "")) ? "[ref]" : source;
    case "mention":
      return USERS.has(source.slice(1).toLowerCase()) ? "[ref]" : `[unknown:${source}]`;
    case "handle":
      return source;
    case "config":
    case "symbol":
      return "[sym]";
    case "source":
      return "[src]";
    case "image":
    case "meme":
    case "macro":
      return "[img]";
    case "key":
      // Without keys, nothing.
      return /^\{key[ \n]*\}$/.test(source) ? "" : "[key]";
    case "icon":
    case "nav":
    case "anchor":
      return `[${token.kind}]`;
    default:
      return `[?${token.kind}]`;
  }
}

function normalize(skeleton: string): string {
  let out = skeleton;
  // Empty formatting renders as nothing: the closing marker of formatting
  // that a browser ended early, or formatting around an anchor.
  for (let before = ""; before !== out;) {
    before = out;
    out = out.replace(/<(b|i|s|u|h)><\/\1>/g, "");
  }
  return (
    out
      // Several keys render as several elements.
      .replace(/(\[key\])+/g, "[key]")
      // Phorge drops the whitespace before a name alone on a line when no
      // macro has the name (PhabricatorImageMacroRemarkupRule returns only
      // the name); it renders the same.
      .replace(/\n[ \t]+/g, "\n")
  );
}

function matches(expected: string, actual: string): boolean {
  const escaped = expected.replace(/[.*+?^${}()|[\]\\]/g, "\\$&").replaceAll(ANY, "[^\\]]*");
  return new RegExp(`^${escaped}$`).test(actual);
}

// Kinds of tokens stored before the hyperlink rule's last pass.
const STORED_BEFORE_URLS = new Set(
  "url eval monospace link config nav key icon source symbol image meme anchor".split(" "),
);

/** Why the tokens can not be compared with the dev instance's rendering, or null. */
function exclusion(text: string, tokens: InlineToken[]): string | null {
  const all = (list: InlineToken[]): InlineToken[] => list.flatMap((t) => [t, ...all(t.children ?? [])]);
  for (const token of all(tokens)) {
    // An embedded file renders as a <div>, and a browser reopens formatting
    // (after misnested tags) only inside it, not around it.
    const first = token.children?.[0];
    if (
      FORMAT_TAGS[token.kind] &&
      token.contentFrom === token.from &&
      first?.kind === "embed" &&
      first.from === token.from
    ) {
      return "an embed where a browser reopens formatting";
    }
    // Phorge breaks a token followed by a URI, as the hyperlink rule (its
    // pass for bare URIs, after the ones for "<uri>" and "{uri}") matches
    // from inside it ("`a`http://x.y" renders as "1Zhttp://x.y"); the
    // tokenizer leaves the URI as text.
    if (STORED_BEFORE_URLS.has(token.kind) && /^\w*:\/\//.test(text.slice(token.to))) {
      return "a token stored before the hyperlink rule, followed by a URI";
    }
    // Phorge stores "@{config:…}" with an unknown key as a Diviner symbol,
    // but not after a word character; the tokenizer does not know the keys.
    const key = text.slice(token.from + "@{config:".length, token.to - 1);
    if (token.kind === "config" && !CONFIG.has(key) && /\w$/.test(text.slice(0, token.from))) {
      return "unknown config key after a word character";
    }
  }
  return null;
}

describe("tokenizeInline", () => {
  it("finds what Phorge's inline rules render", () => {
    // A broken generation must not make this pass on nothing.
    expect(fixtures.length).toBeGreaterThan(5000);
    const excluded: string[] = [];
    const mismatches = fixtures.flatMap(({ text, html }) => {
      // The dev container runs PHP 7.4, which orders the rules differently.
      const tokens = tokenizeInline(text, { isMacro, php7: true });
      const reason = exclusion(text, tokens);
      if (reason) {
        excluded.push(reason);
        return [];
      }
      const trimmed = text.replace(/^[ \t\n\r\0\x0B]+|[ \t\n\r\0\x0B]+$/g, "");
      const start = text.indexOf(trimmed);
      const expected = normalize(tokenSkeleton(text, tokens, start, start + trimmed.length));
      const actual = htmlSkeleton(html);
      return matches(expected, actual) ? [] : [{ text, expected, actual }];
    });
    expect(mismatches.slice(0, 3)).toEqual([]);
    // Exclusions are rare and named; most of them would hide a broken rule.
    expect(excluded.length).toBeLessThan(fixtures.length / 50);
    // Over 5000 texts: about 2 s on a fast machine, more on a busy or slow one (CI).
  }, 30_000);

  const show = (text: string, options = {}): unknown[] => {
    const list = (tokens: InlineToken[]): unknown[] =>
      tokens.map((t) => {
        const shown: unknown[] = [t.kind, text.slice(t.from, t.to)];
        if (t.contentFrom !== undefined) {
          shown.push(text.slice(t.contentFrom, t.contentTo));
        }
        if (t.children?.length) {
          shown.push(list(t.children));
        }
        return shown;
      });
    return list(tokenizeInline(text, options));
  };

  it("has the markers around the content", () => {
    expect(show("**a //b//** ~~c~~ __d__ !!e!!!! `f` ##g##")).toEqual([
      ["bold", "**a //b//**", "a //b//", [["italic", "//b//", "b"]]],
      ["del", "~~c~~", "c"],
      ["underline", "__d__", "d"],
      ["highlight", "!!e!!!!", "e!!"],
      ["monospace", "`f`", "f"],
      ["monospace", "##g##", "g"],
    ]);
  });

  it("splits formatting that crosses other formatting like a browser", () => {
    // <em> is reopened after </strong>; its second part has no opening marker.
    expect(show("**a //b** c//")).toEqual([
      ["bold", "**a //b**", "a //b", [["italic", "//b", "b"]]],
      ["italic", " c//", " c"],
    ]);
    // <del> ends with </strong>; its closing marker renders as nothing.
    expect(show("**a ~~b** c~~")).toEqual([
      ["bold", "**a ~~b**", "a ~~b", [["del", "~~b", "b"]]],
      ["del", "~~", ""],
    ]);
  });

  it("has the content of links and URLs", () => {
    expect(show("[[ /w/x | the name ]] [[ page ]] [n](https://x.y/z) <https://x.y> https://x.y/a.")).toEqual([
      ["link", "[[ /w/x | the name ]]", "the name"],
      ["link", "[[ page ]]"],
      ["link", "[n](https://x.y/z)", "n"],
      ["url", "<https://x.y>", "https://x.y"],
      ["url", "https://x.y/a"],
    ]);
  });

  it("has what renders inside monospaced text", () => {
    expect(show("`${{{strings.platform.server.name}}}`")).toEqual([
      [
        "monospace",
        "`${{{strings.platform.server.name}}}`",
        "${{{strings.platform.server.name}}}",
        [["eval", "${{{strings.platform.server.name}}}"]],
      ],
    ]);
  });

  it("finds no color codes, as the project rule comes first", () => {
    // "{#fff}" is a project embed; with a word after it, "#ff0000" is a project.
    expect(show("{#fff} {#ff0000}x")).toEqual([
      ["embed", "{#fff}"],
      ["project", "#ff0000"],
    ]);
  });

  it("asks which names are macros", () => {
    expect(show("rmecat\n__init__")).toEqual([
      ["macro", "rmecat"],
      ["macro", "__init__"],
    ]);
    expect(show("rmecat\n__init__", { isMacro })).toEqual([
      ["macro", "rmecat"],
      ["underline", "__init__", "init"],
    ]);
  });

  // Rendered the same whether stored or not (without repositories, a commit
  // renders as its text), so only here.
  it("finds commits and mocks like Phorge's patterns", () => {
    expect(show("abcdef abcdef1 rXYZ rXYZ12 R1:abcde M12/3/ M12/")).toEqual([
      ["object", "abcdef1"],
      ["object", "rXYZ"],
      ["object", "rXYZ12"],
      ["object", "R1:abcde"],
      ["object", "M12/3/"],
      ["object", "M12"],
    ]);
  });

  it("keeps a token Phorge's hyperlink rule would break", () => {
    // Phorge renders "1Zhttp://x.y" (the token's tail, unlinked).
    expect(show("`a`http://x.y")).toEqual([["monospace", "`a`", "a"]]);
  });

  it("has offsets into the untrimmed text", () => {
    const tokens = tokenizeInline("  \n **x** \n");
    expect(tokens.map((t) => [t.from, t.to, t.contentFrom, t.contentTo])).toEqual([[4, 9, 6, 7]]);
  });
});
